        <span class="league-mark"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span> Bowling league</span>
        <span>Six teams</span>
      </header>
      <div class="schedule-main">
        <h2 class="title">Final<span>Night</span></h2>
        <div class="scene" aria-hidden="true">
          <div class="lane"></div>
          <div class="pin pin-left"></div><div class="pin pin-right"></div><div class="pin pin-center"></div>
          <div class="ball"><i></i><i></i><i></i></div>
