        <li><b>6:00 <small>PM</small></b><span>Doors open</span></li>
        <li><b>6:20 <small>PM</small></b><span>Warmups</span></li>
        <li><b>6:40 <small>PM</small></b><span>Two games begin</span></li>
        <li><b>8:30 <small>PM</small></b><span>Recognition</span></li>
