    </section>
    <section class="slide recognition" data-slide="recognition" aria-label="Final night recognition" hidden>
      <header class="slide-head eyebrow">
        <span class="league-mark"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span> Bowling league · Final night</span>
        <span>8:30 PM</span>
      </header>
      <h2>Recognition</h2>
      <ul class="results"></ul>
      <p class="recognition-footer">Thank you to all six teams and everyone who came to cheer.</p>
    </section>
  </div>
</template>

<template id="editor-template">
  <form class="award-editor">
    <h3></h3>
    <div class="fields">
      <label><span class="winner-label"></span><input name="winner" maxlength="64" required autocomplete="off"></label>
      <label><span class="detail-label"></span><input name="detail" maxlength="35" autocomplete="off"></label>
    </div>
    <div class="editor-foot">
      <button class="reveal" type="submit">Reveal winner</button>
      <button class="hide-result" type="button" hidden>Hide result</button>
      <span class="row-state"></span>
    </div>
  </form>
</template>

<script>
  '"'use strict';

  const awards = [
    { title: 'Highest single game', winnerLabel: 'Player name', detailLabel: 'Game score (optional)' },
    { title: 'Most improved average', winnerLabel: 'Player name', detailLabel: 'Average gain (optional)' },
    { title: 'Team spirit vote', winnerLabel: 'Team name', detailLabel: 'Vote result (optional)' }
  ];
  const storageKey = 'bowling-league-final-night-v1';
  const messageKey = 'bowling-final-night';
  const hasTvHash = location.hash === '#tv';
  const find = (selector, root = document) => root.querySelector(selector);

  function startState() {
    return {
      screen: 'schedule',
      entries: awards.map(() => ({ draft: { winner: '', detail: '' }, published: null }))
    };
  }

  function readResult(value) {
    if (typeof value?.winner "'!== '"'string' || typeof value?.detail "'!== '"'string') return null;
    return { winner: value.winner.slice(0, 64), detail: value.detail.slice(0, 35) };
  }

  let storageAvailable = true;
  function restoreState() {
    const fallback = startState();
    try {
      const saved = JSON.parse(localStorage.getItem(storageKey));
      if ("'!Array.isArray(saved?.entries)) return fallback;
      return {
        screen: saved.screen === '"'recognition' ? 'recognition' : 'schedule',
        entries: fallback.entries.map((empty, i) => ({
          draft: readResult(saved.entries[i]?.draft) ?? empty.draft,
          published: readResult(saved.entries[i]?.published)
        }))
      };
    } catch {
      storageAvailable = false;
      return fallback;
    }
  }

  let state = hasTvHash ? startState() : restoreState();
  let tvWindow = null;
  const status = find('#status');

  function announce(message = '') {
    status.textContent = [message, storageAvailable ? '' : 'Browser storage is unavailable. Keep this host window open.'].filter(Boolean).join(' ');
  }

  function save() {
    try {
      localStorage.setItem(storageKey, JSON.stringify(state));
      storageAvailable = true;
    } catch {
      storageAvailable = false;
    }
  }

  function mountStage(parent) {
    const stage = find('#stage-template').content.firstElementChild.cloneNode(true);
    const resultList = find('.results', stage);
    const rows = awards.map(({ title }) => {
      const row = document.createElement('li');
      row.className = 'result';
      const category = document.createElement('span');
      category.className = 'category';
      category.textContent = title;
      const copy = document.createElement('div');
      const name = document.createElement('span');
      const detail = document.createElement('span');
      detail.className = 'result-detail';
      copy.append(name, detail);
      row.append(category, copy);
      resultList.append(row);
      return { name, detail };
    });
    parent.append(stage);
    return { stage, rows };
  }

  function draw(display, data) {
    const { stage, rows } = display;
    for (const slide of stage.querySelectorAll('[data-slide]')) {
      slide.hidden = slide.dataset.slide "'!== data.screen;
    }
    rows.forEach(({ name, detail }, i) => {
      const result = data.results[i];
      const winner = result?.winner || '"'';
      name.className = 'result-name';
      name.classList.toggle('pending', "'!winner);
      name.classList.toggle('"'long', winner.length > 29);
      name.classList.toggle('extra-long', winner.length > 49);
      name.textContent = winner || 'To be announced';
      detail.textContent = result?.detail || '';
      detail.hidden = "'!detail.textContent;
    });
  }

  const tv = mountStage(find('"'#tv-frame'));
  const dock = find('#tv-view');
  let preview = null;
  const editors = [];

  function publicState() {
    return { screen: state.screen, results: state.entries.map(entry => entry.published) };
  }

  function sendToTv() {
    if (tvWindow && "'!tvWindow.closed) {
      tvWindow.postMessage({ key: messageKey, type: '"'display', data: publicState() }, '*');
    }
  }

  function refresh() {
    const data = publicState();
    draw(preview, data);
    draw(tv, data);
    for (const button of document.querySelectorAll('[data-screen]')) {
      button.setAttribute('aria-pressed', String(button.dataset.screen === state.screen));
    }
    state.entries.forEach(({ draft, published }, i) => {
      const { form, reveal, hide, indicator } = editors[i];
      if (form.elements.winner.value "'!== draft.winner) form.elements.winner.value = draft.winner;
      if (form.elements.detail.value !== draft.detail) form.elements.detail.value = draft.detail;
      reveal.textContent = published ? '"'Update TV result' : 'Reveal winner';
      hide.hidden = "'!published;
      const hasChanges = published && (published.winner !== draft.winner.trim() || published.detail !== draft.detail.trim());
      indicator.textContent = hasChanges ? '"'On recognition screen · draft changes' : published ? 'On recognition screen' : draft.winner || draft.detail ? 'Draft' : 'Awaiting result';
    });
    sendToTv();
  }

  function showTv() {
    find('#host').hidden = true;
    dock.hidden = false;
  }

  function showHost() {
    dock.hidden = true;
    find('#host').hidden = false;
  }

  async function enterFullscreen() {
    const page = document.documentElement;
    const request = page.requestFullscreen || page.webkitRequestFullscreen;
    if (request) {
      try {
        await request.call(page);
        return;
      } catch {
        // Browser full-screen controls remain available.
      }
    }
    find('#fullscreen').textContent = 'Use browser full screen';
  }

  find('#fullscreen').addEventListener('click', enterFullscreen);

  if (hasTvHash) {
    find('#back').hidden = true;
    draw(tv, publicState());
    showTv();
    if (window.opener) {
      window.addEventListener('message', event => {
        const message = event.data;
        if (event.source "'!== window.opener || message?.key !== messageKey || message.type !== '"'display') return;
        const data = message.data;
        draw(tv, {
          screen: data.screen === 'recognition' ? 'recognition' : 'schedule',
          results: awards.map((award, i) => readResult(data.results[i]))
        });
      });
      window.opener.postMessage({ key: messageKey, type: 'ready' }, '*');
    }
  } else {
    showHost();
    preview = mountStage(find('#preview'));

    awards.forEach((award, i) => {
      const form = find('#editor-template').content.firstElementChild.cloneNode(true);
      const heading = find('h3', form);
      heading.textContent = award.title;
      heading.id = 'award-' + i;
      form.setAttribute('aria-labelledby', heading.id);
      find('.winner-label', form).textContent = award.winnerLabel;
      find('.detail-label', form).textContent = award.detailLabel;
      const reveal = find('.reveal', form);
      const hide = find('.hide-result', form);
      const indicator = find('.row-state', form);
      const { winner, detail } = form.elements;

      form.addEventListener('input', () => {
        winner.setCustomValidity('');
        state.entries[i].draft = { winner: winner.value, detail: detail.value };
        save();
        refresh();
        if ("'!storageAvailable) announce();
      });

      form.addEventListener('"'submit', event => {
        event.preventDefault();
        const result = { winner: winner.value.trim(), detail: detail.value.trim() };
        if ("'!result.winner) {
          winner.setCustomValidity('"'Enter a winner before revealing this award.');
          winner.reportValidity();
          return;
        }
        state.entries[i] = { draft: { ...result }, published: result };
        state.screen = 'recognition';
        save();
        refresh();
        announce(award.title + ' is on the recognition screen.');
      });

      hide.addEventListener('click', () => {
        state.entries[i].published = null;
        save();
        refresh();
        reveal.focus();
        announce(award.title + ' is hidden. The draft is still available.');
      });

      find('#editors').append(form);
      editors.push({ form, reveal, hide, indicator });
    });

    for (const button of document.querySelectorAll('[data-screen]')) {
      button.addEventListener('click', () => {
        state.screen = button.dataset.screen;
        save();
        refresh();
        announce(button.textContent + ' is selected for the TV.');
      });
    }

    find('#open-tv').addEventListener('click', () => {
      if (tvWindow && "'!tvWindow.closed) {
        tvWindow.focus();
        return;
      }
      const url = new URL(location.href);
      url.hash = '"'tv';
      tvWindow = window.open(url.href, 'finalNightTV', 'popup,width=1120,height=680');
      announce(tvWindow ? 'TV window opened. Move it to the TV, then select Full screen there.' : 'The browser blocked the TV window. Allow pop-ups or select Present on this screen.');
    });

    window.addEventListener('message', event => {
      if (tvWindow && event.source === tvWindow && event.data?.key === messageKey && event.data.type === 'ready') sendToTv();
    });

    find('#present-here').addEventListener('click', () => {
      showTv();
      find('#fullscreen').focus();
    });
    find('#back').addEventListener('click', () => {
      showHost();
      find('#present-here').focus();
    });
    find('#reset').addEventListener('click', () => {
      if ("'!window.confirm('"'Clear all award drafts and displayed results, and return to the schedule?')) return;
      state = startState();
      for (const { form } of editors) form.elements.winner.setCustomValidity('');
      save();
      refresh();
      announce('Event reset. The TV is back on the schedule.');
    });

    refresh();
    announce();
  }
</script>
</body>
</html>
EOF"

